"""Import one Kuixing candidate in Blender, save editable project + round-trip GLB.
The canonical source and simplifier GLB are never overwritten. No other assets.
"""
import bpy,sys,json,argparse,time,hashlib
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--root',required=True);p.add_argument('--level',choices=['LOD0','LOD1','LOD2'],required=True);a=p.parse_args(sys.argv[sys.argv.index('--')+1:]);r=Path(a.root)/'assets/kuixing-pilot';level=a.level;t=time.perf_counter()
bpy.ops.wm.read_factory_settings(use_empty=True);src=r/'export'/('kuixing_'+level+'.glb');bpy.ops.import_scene.gltf(filepath=str(src));meshes=[o for o in bpy.context.scene.objects if o.type=='MESH'];assert len(meshes)==1;o=meshes[0];o.name='Kuixing_'+level+'_Unapproved';o['provenance']='Original high retained separately at source/kuixing_high.blend; candidate generated by attribute-aware meshoptimizer, not an applied Blender decimation.';o['source_report']=str(r/'reports'/(level+'.json'));o['approved_for_game']=False
