bpy.ops.wm.save_as_mainfile(filepath=str(r/'optimized'/('kuixing_'+level+'.blend')),compress=True)
folder=r/'export/blender_roundtrip';folder.mkdir(exist_ok=True);dest=folder/('kuixing_'+level+'.glb');bpy.ops.export_scene.gltf(filepath=str(dest),export_format='GLB',export_apply=False,export_yup=True,export_normals=True,export_materials='EXPORT')
report={'blender':bpy.app.version_string,'level':level,'input':str(src),'blend':str(r/'optimized'/('kuixing_'+level+'.blend')),'output':str(dest),'vertices_in_blender':len(o.data.vertices),'triangles_in_blender':sum(len(p.vertices)-2 for p in o.data.polygons),'seconds':time.perf_counter()-t,'output_bytes':dest.stat().st_size,'approved':False,'note':'Blender-exported candidate is a separate QA deliverable; runtime pilot uses canonical GLB with byte-identical source maps.'};(r/'reports'/('blender-'+level+'.json')).write_text(json.dumps(report,indent=2),encoding='utf8');print(json.dumps(report),flush=True)
